+        hits,
+        ['POST /v2/video_generation'],
+        reason:
+            'the submit ran, no poll did — the render keeps going '
+            'remotely',
+      );
+    });
+
+    test(
+      'the tool result carries the anchor sentence and the task id',
+      () async {
+        final client = MockClient((request) async {
+          final path = request.url.path;
